sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue =='') {
        g_form.setVisible('u_vendor_name', false);
        g_form.setVisible('u_vendor_number', false);
        g_form.setVisible('u_vendor_address', false);
        g_form.setVisible('u_vendor_email', false);
        g_form.setVisible('u_ert', false);
        return;
    }
    if (newValue == 'vendor') {
        g_form.setVisible('u_vendor_name', true);
        g_form.setVisible('u_vendor_number', true);
        g_form.setVisible('u_vendor_address', true);
        g_form.setVisible('u_vendor_email', true);
        g_form.setVisible('u_ert', true);
    } else {
        g_form.setVisible('u_vendor_name', false);
        g_form.setVisible('u_vendor_number', false);
        g_form.setVisible('u_vendor_address', false);
        g_form.setVisible('u_vendor_email', false);
        g_form.setVisible('u_ert', false);
        //Type appropriate comment here, and begin script below
    }
}
